  {
    "Name": "Test",
    "ResourceKey": "Test",
    "RawString": "<html>
<head>
    <title>User Activity Report for [model[start]] to [model[end]]</title>
    <style>
        body { padding: 0 20px; font-size: [theme[font.size]]; font-family: [theme[font.family]]; }

        h1 {
            width: 80%;
            border-bottom: solid 2px [theme[colours.primary]];
		    color: [theme[colours.primary]];
        }

        h2 {
            width: 80%;
            border-bottom: solid 2px [theme[colours.secondary]];
		    color: [theme[colours.secondary]];
        }

        table { 		
            box-shadow: [theme[shadows]];
            -moz-box-shadow: [theme[shadows]];
            -webkit-box-shadow: [theme[shadows]];
            border-width: [theme[border.width]];
            border-radius: [theme[border.radius]];
            border: [theme[border.style]];
            margin-bottom: 20px; 
        }

        thead { background: #EFEFEF; }
        tr { border: [theme[border.style]]; }
        th { text-align: left; padding: 2px 6px; }
        td { padding: 4px; }
    </style>
</head>
<body>
    <h1 style="color: [theme[colours.primary]];">User Activity Report for [model[fromYear]]-[model[fromMonth]]-01 to [model[toYear]]-[model[toMonth]]-01</h1>
    <h2 style="color: [theme[colours.primary]];">Users</h2>
    <table>
        <thead>
            <tr>
                <th style="width: 150px;">Id</th><th style="width: 200px;">Name</th><th style="width: 300px;">Email</th>
            </tr>
        </thead>
        <tbody>
            [execute]
                string result = string.Empty;

                foreach(var user in model.Data.Users)
                    result += $"<tr><td>{user.Id}</td><td>{user.DisplayName}</td><td>{user.Email}</td></tr>";

                return result;
            [/execute]
        </tbody>
    </table>

    <h2 style="color: [theme[colours.primary]];">Sessions</h2>
    <table>
        <thead>
            <tr>
                <th>Date</th><th>Name</th><th>Email</th><th>Count</th><th>Page Hits</th><th>Api Calls</th>
            </tr>
        </thead>
        <tbody>
            [execute]
                string result = string.Empty;

                foreach(var session in model.Data.Sessions)
                    result += $"<tr><td>{session.Date}</td><td>{session.DisplayName}</td><td>{session.Email}</td><td>{session.SessionCount}</td><td>{session.PageHits}</td><td>{session.ApiCalls}</td></tr>";

                return result;
            [/execute]
        </tbody>
    </table>
</body>
</html>",
